    def main(self, x: pl.Tensor[[16, 64], pl.FP32]) -> pl.Tensor[[8, 64], pl.FP32]:
        n: pl.Scalar[pl.INDEX] = pl.tensor.read(x, [0])  # dynamic scalar
        valid_len: pl.Scalar[pl.INDEX] = pl.min(64, n)
