    for (...) {
        for (...) {
            params_t0.add_output(c__ssa_v1_ci);  // BUG: should be ext_c
            TaskOutputTensors outs_t0 = pto2_rt_submit_aic_task(0, params_t0);
        }
    }
}
// ext_c is never written — host reads garbage
```

