    [](const std::vector<ExprPtr>& args, ...) -> ConversionResult {
      bool a_trans = GetKwargOr<bool>(kwargs, "a_trans", false);
      bool b_trans = GetKwargOr<bool>(kwargs, "b_trans", false);
